<style scoped>
.tech-marquee {
  width: min(640px, 90vw);
  /* Marge intérieure : place pour l'agrandissement au survol, que overflow couperait */
  margin: 2rem auto 0;
  padding: 0.5rem 0;
  overflow: hidden;
  /* Les logos apparaissent et disparaissent en fondu sur les bords */
  -webkit-mask-image: linear-gradient(to right, transparent, #000 15%, #000 85%, transparent);
  mask-image: linear-gradient(to right, transparent, #000 15%, #000 85%, transparent);
}

.rail {
  display: flex;
  width: max-content;
  animation: scroll 45s linear infinite;
}

.tech-marquee:hover .rail {
  animation-play-state: paused;
}

.track {
  display: flex;
  gap: 2.25rem;
  margin: 0;
  padding: 0 2.25rem 0 0;
  list-style: none;
}

.track li {
  display: flex;
  cursor: default;
}

.track svg {
  width: 28px;
  height: 28px;
  fill: rgba(255, 255, 255, 0.5);
  transition: fill 0.3s, transform 0.3s;
}

.track li:hover svg {
  fill: var(--brand);
  transform: scale(1.15);
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

@keyframes scroll {
  to {
    transform: translateX(-50%);
  }
}

/* Animations réduites : les logos restent en place, sur plusieurs lignes */
@media (prefers-reduced-motion: reduce) {
  .tech-marquee {
    -webkit-mask-image: none;
    mask-image: none;
  }

  .rail {
    width: auto;
    animation: none;
  }

  .track {
    flex-wrap: wrap;
    justify-content: center;
    gap: 1.25rem;
    padding: 0;
  }

  .track[aria-hidden='true'] {
    display: none;
  }
}

@media (max-width: 768px) {
  .tech-marquee {
    margin-top: 1.5rem;
  }

  .track {
    gap: 1.75rem;
    padding-right: 1.75rem;
  }

  .track svg {
    width: 24px;
    height: 24px;
  }
}
